const err = $input.first().json;
const text = JSON.stringify(err ?? {}).toLowerCase();
const missing = text.includes("doesn't exist") || text.includes('does not exist');

if (missing) {
  // La coleccion de pruebas no existe -- no hay nada que borrar. Se devuelve un
  // resultado exitoso sintetico en vez de fallar el evento products/delete.
  return [{
    json: {
      result: { status: 'no_op_collection_missing' },
      status: 'ok',
      note: "La coleccion BabysWorld_Catalogo no existia -- nada que borrar."
    }
  }];
}

// Cualquier otro error: se relanza tal cual, la ejecucion debe quedar en estado de error.
throw new Error(typeof err === 'string' ? err : JSON.stringify(err));

